import{_ as t,a as o}from"./chunks/song.vmbSg_v5.js";import{_ as a,o as s,c as n,a2 as d}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/file.DMxnwLxj.svg",w=JSON.parse('{"title":"Object Model","description":"","frontmatter":{},"headers":[],"relativePath":"OBJECT_MODEL.md","filePath":"OBJECT_MODEL.md"}'),i={name:"OBJECT_MODEL.md"};function c(h,e,l,p,g,m){return s(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="object-model" tabindex="-1">Object Model <a class="header-anchor" href="#object-model" aria-label="Permalink to &quot;Object Model&quot;">​</a></h1><p>A file is a set of songs, which share its patterns, scales, generators, chains and grooves. This page covers the Set File page, the Songs page and each song&#39;s settings.</p><h2 id="set-file-page" tabindex="-1">Set File Page <a class="header-anchor" href="#set-file-page" aria-label="Permalink to &quot;Set File Page&quot;">​</a></h2><p><img src="'+r+'" alt="The Set File page"></p><p>Press <code>F</code> on the main screen to open the Set File page, which holds the set itself: what the file says about the set, the defaults every song starts from, and the keys that start a new set or save under a new name.</p><p>The loose settings come first, in alphabetical order, then two sections, closed until opened with <code>Space</code> or <code>Enter</code>: Notes &amp; Octaves, the defaults every pattern starts from, and Visualizers.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Author</td><td>Who wrote the set, also only for people reading the file.</td></tr><tr><td>Default follow action</td><td>What a clip&#39;s Advance does in real-time playback, unless the clip sets its own: &quot;With Scene&quot;, &quot;Next&quot; or &quot;Off&quot;. No export reads it. <code>Enter</code> chooses.</td></tr><tr><td>Description, Notes</td><td>What the set is, in a line, and anything else to say about it; see Description and Notes below.</td></tr><tr><td>Protected</td><td>Whether the file is protected from being saved over. <code>Space</code> or <code>Enter</code> turns it on or off. Every set in <code>examples/</code> is protected, so trying things in a demo can&#39;t spoil the demo: <code>Ctrl+S</code> offers to save a copy under another name instead, and the copy is yours and isn&#39;t protected. A set you start yourself isn&#39;t protected unless you turn this on.</td></tr><tr><td>Title</td><td>The set&#39;s name, for anyone reading or sharing the file, such as in git. It doesn&#39;t change how anything plays, and <code>Bksp</code> clears it.</td></tr></tbody></table><p><strong>Notes &amp; Octaves</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Default drum octave</td><td>The octave a new drum note gets.</td></tr><tr><td>Default octave</td><td>The octave a new note gets, in the set&#39;s octave labels.</td></tr><tr><td>Octave labels</td><td>How octaves are numbered on screen: as Live labels them, where middle C is C3, or in llamatron&#39;s own numbering from 0, where middle C is C5. <code>Enter</code> chooses. The setting changes only what you see, while the notes and the file stay the same. See Octave Numbering below.</td></tr><tr><td>Step size</td><td>How long each step of a pattern is, unless the pattern sets its own, from 1/64 to a whole note. <code>Enter</code> chooses from the list. A pattern&#39;s own step size is set in the pattern editor with <code>E</code>.</td></tr></tbody></table><p><strong>Visualizers</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Visualizer</td><td>The visualizer mode Arrange&#39;s visualizer key shows first, unless a song names its own. <code>Enter</code> chooses.</td></tr><tr><td>Hide Visualizers</td><td>The modes the visualizer key leaves out, listed by name. <code>Enter</code> opens a list where <code>Space</code> picks or unpicks each mode, <code>Enter</code> keeps the choice and <code>Esc</code> changes nothing.</td></tr></tbody></table><p>Below the settings, two buttons save and open without remembering a key: <code>↓</code> from the last setting reaches them, <code>←</code> and <code>→</code> choose, and <code>Enter</code> on <strong>Save</strong> saves the set, as <code>Ctrl+S</code> does, and <code>Enter</code> on <strong>Open</strong> opens another set, as <code>Ctrl+O</code> does. Below the buttons, the page shows the path of the set&#39;s file and where the current song exports. <a href="./GETTING_STARTED#opening-and-saving">Opening and Saving</a> describes the keys <code>N</code> (New) and <code>W</code> (Save As).</p><h3 id="description-and-notes" tabindex="-1">Description and Notes <a class="header-anchor" href="#description-and-notes" aria-label="Permalink to &quot;Description and Notes&quot;">​</a></h3><p>The Description is one line saying what the set is, such as the tune it plays: <code>The Wellerman</code>, or <code>a C major scale</code>. <code>Enter</code> types it and <code>Bksp</code> clears it, as for the title. <a href="./DEMOS">About Demos</a> shows each example&#39;s description.</p><p>The Notes are as long as you like, for anyone reading or sharing the file: what each song or scene is for, or what to try. The notes don&#39;t change how anything plays. The Set File page shows their first line, or <code>not set</code>, and the notes are saved at the top of the file, where they read as plain text.</p><h3 id="notes-page" tabindex="-1">Notes Page <a class="header-anchor" href="#notes-page" aria-label="Permalink to &quot;Notes Page&quot;">​</a></h3><p><code>Enter</code> on Notes opens the Notes page for editing. Typing adds text at the cursor, <code>Enter</code> starts a new line, <code>Bksp</code> erases, and the arrows move the cursor; while editing, every letter is text, and only <code>Tab</code>, <code>Esc</code> and the arrows act as keys. Under the text are two buttons, Save and Cancel. <code>Tab</code> moves onto them, Left and Right choose one, <code>Enter</code> presses it, and <code>Tab</code> again returns to the text.</p><p>Save keeps the text in the set, to be saved with the set, as one change for undo. Cancel, or <code>Esc</code> anywhere on the page, throws away what was typed since editing began. Either one leaves the page reading, where Up and Down scroll, <code>E</code> starts editing again, <code>Bksp</code> clears all of the notes after asking, and <code>Esc</code> goes back to the Set File page. A protected set&#39;s notes open for reading only, and <code>E</code> and <code>Bksp</code> aren&#39;t offered until Protected is turned off.</p><h3 id="octave-numbering" tabindex="-1">Octave Numbering <a class="header-anchor" href="#octave-numbering" aria-label="Permalink to &quot;Octave Numbering&quot;">​</a></h3><p>Octaves are shown as Live labels them unless the Octave labels setting says otherwise. With Live&#39;s labels, octaves run from -2 to 8, and degree 1 of C major in octave 3 is middle C (C3, MIDI note 60). llamatron&#39;s own labels count from 0, where C0 is MIDI note 0, so middle C is C5 and the top octave is 10. The file always stores llamatron&#39;s numbering, whichever labels you see, and a file saved by an earlier version of llamatron, which stored Live&#39;s numbering, is converted when it loads.</p><h2 id="songs-page" tabindex="-1">Songs Page <a class="header-anchor" href="#songs-page" aria-label="Permalink to &quot;Songs Page&quot;">​</a></h2><p><img src="'+t+'" alt="The Songs page"></p><p>Press <code>S</code> on the main screen to open the Songs page. The set&#39;s songs are listed with their tempo, scale, and number of tracks and scenes, and <code>●</code> marks the current song: the song Registers and Arrange edit and <code>Ctrl+X</code> exports. Each song has its own tracks, scenes and registers, while all of them share the set&#39;s patterns, scales, generators, chains and grooves, so the same pattern can play in every song.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Space</code></td><td>Make the selected song current</td></tr><tr><td><code>Enter</code></td><td>Make it current and open its settings</td></tr><tr><td><code>A</code></td><td>Add a song, asking for its name</td></tr><tr><td><code>N</code></td><td>Rename it. The song&#39;s name and the set&#39;s are independent.</td></tr><tr><td><code>C</code></td><td>Copy it, with its tracks, scenes and registers, named with the next free number: a copy of <code>verse</code> is <code>verse 2</code>, and a copy of <code>verse 2</code> is <code>verse 3</code>. Every copy on every page is named this way.</td></tr><tr><td><code>M</code></td><td>Pick it up: <code>↑↓</code> carry it, and <code>Enter</code> drops it</td></tr><tr><td><code>S</code></td><td>Sort the list by name</td></tr><tr><td><code>Bksp</code></td><td>Delete it, after asking. The set always keeps at least one song.</td></tr></tbody></table><h3 id="song-page" tabindex="-1">Song Page <a class="header-anchor" href="#song-page" aria-label="Permalink to &quot;Song Page&quot;">​</a></h3><p><img src="'+o+'" alt="The Song page"></p><p><code>Enter</code> on a song opens the Song page.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td>The song&#39;s name, shown in the header. <code>Enter</code> renames it, the same as <code>N</code> on the Songs page.</td></tr><tr><td>Tempo</td><td>Beats per minute for the whole song, from 10 to 999. A scene can set its own.</td></tr><tr><td>Time signature</td><td>Beats over a note value, 4/4 to start. <code>[</code> and <code>]</code> step through the common ones, and <code>Enter</code> types any other, such as 7/8. The time signature changes nothing about when notes play: the pattern editor marks its beats with bold numbers and double lines, real-time launches wait for its bars, and the exports carry it so that Live and other DAWs draw the right bars. A pattern can have its own, set in the pattern editor through <code>R</code> (Reconfigure).</td></tr><tr><td>Entry size</td><td>How long a note placed on a pattern&#39;s piano roll lasts, when the pattern doesn&#39;t set its own: one of the step sizes, or <code>(one step)</code> of the pattern, which a new song starts with. <code>[</code> and <code>]</code> step through the sizes, <code>Enter</code> picks one from a list, and <code>Bksp</code> goes back to one step.</td></tr><tr><td>Scale</td><td>The song&#39;s scale, from the Scales page; a scene or a clip can use another. <code>Bksp</code> sets no scale, in which case patterns with degrees can&#39;t play or export.</td></tr><tr><td>Seed</td><td>With no seed, which a new song starts with, every play and export is a new take: the notes probability drops, random play directions and random arpeggiators all come out differently each time. A seed plays the same take every time, and a different seed gives a different take. <code>Bksp</code> clears it.</td></tr><tr><td>Groove</td><td>The swing or other timing feel every clip plays with, unless its scene or track chooses another, from the Grooves page. <code>none</code>, which a new song starts with, plays straight. <code>[</code> and <code>]</code> step through the grooves, and <code>Enter</code> picks one from a list.</td></tr><tr><td>Genre</td><td>A word or two saying what kind of music the song is, such as Folk or Electronic, only for people to read. <code>Enter</code> types it and <code>Bksp</code> clears it. <a href="./DEMOS">About Demos</a> groups the examples by genre.</td></tr><tr><td>Live response</td><td>When an edit made while the song plays is heard: &quot;next bar&quot;, the default, &quot;clip restart&quot;, at each playing clip&#39;s next pass, or &quot;ASAP&quot;, at once.</td></tr><tr><td>Export</td><td><code>Enter</code> here exports this song, the same as <code>Ctrl+X</code> anywhere, asking which kind of output first.</td></tr></tbody></table><h2 id="set-files" tabindex="-1">Set Files <a class="header-anchor" href="#set-files" aria-label="Permalink to &quot;Set Files&quot;">​</a></h2><p>Sets are saved as YAML, and each file records the version of llamatron that saved it, which the About dialog also shows. The format is mainly for llamatron to read, but it stays readable so that sets can be compared in version control, and the files in <code>examples/</code> show every part of it.</p><p>The shared sections come first, <code>scales</code>, <code>patterns</code>, the generators, <code>chains</code> and <code>grooves</code>, and then <code>songs</code> holds each song by name, with its tempo, scale, seed, groove, registers, tracks and scenes. Patterns are stored the way the editor shows them, with one list per row, so a change in the tracker makes a small change to the file. Every setting has a default, so a file can leave out anything it doesn&#39;t need, and a file written by an older version still loads: a file saved before llamatron 1.0.39 held one song and becomes a set of one song named after the file, and a file saved before llamatron 1.0.30, which stored Live&#39;s octave numbering, is moved up when it loads and written the new way when saved.</p>',31)])])}const b=a(i,[["render",c]]);export{w as __pageData,b as default};
